def _ollama_conn(payload, timeout):
    # Direct HTTP to the local Ollama. This used to shell out to curl, which
    # made the model path depend on a subprocess, on PATH, and on whatever
    # proxy variables the notebook environment happens to export -- while the
    # kernel's own proxy reached the same server with Python and always
    # worked. Measured on a live kernel: the proxied calls returned 200 while
    # the curl-based streaming call returned nothing in 200ms, six times out
    # of six. http.client has no proxy handling at all, so the two paths can
    # no longer disagree about whether the model is reachable.
    import http.client
    c = http.client.HTTPConnection('127.0.0.1', 11434, timeout=timeout)
    c.request('POST', '/api/chat', body=json.dumps(payload).encode(),
              headers={'Content-Type': 'application/json'})
    return c, c.getresponse()

def _engine_error(text):
    # Say what actually happened. The old placeholder '(model timeout/error)'
    # made a refused connection, a bad payload and a dead server look
    # identical, which is why this took a live kernel to diagnose.
    return {'message': {'content': '(engine error: '
            + str(text)[:160].replace(chr(10), ' ').strip() + ')'}, 'done': True}

def ollama_chat(payload, timeout=600):
    c = None
    try:
        c, r = _ollama_conn(payload, timeout)
        raw = r.read().decode('utf-8', 'replace')
        try: return json.loads(raw)
        except Exception: return _engine_error(raw or 'empty response')
    except Exception as e:
        return _engine_error(e or e.__class__.__name__)
    finally:
        try:
            if c: c.close()
        except Exception: pass

def ollama_stream(payload, push, timeout=1200):
    # FIX (audit 4.9): stream:true, forwarding every content delta as it lands
    # instead of buffering the whole answer. Returns the same aggregated shape
    # ollama_chat returned, so the agent loop below is unchanged. push(delta)
    # returns False once the client is gone, which stops the read early.
    agg = {'message': {'role':'assistant','content':''}, 'done': False}
    tcs, ths, err, last, status = [], [], '', '', 0
    c = None
    try:
        c, r = _ollama_conn(payload, timeout)
        status = r.status
        if status != 200:
            # Recorded, not swallowed: an error body used to be indistinguishable
            # from an empty one, which is what made this untraceable.
            err = 'HTTP %d %s' % (status, r.read().decode('utf-8', 'replace')[:1200])
        else:
            for raw in r:
                raw = raw.strip()
                if not raw: continue
                last = raw[:200]
                try: ch = json.loads(raw)
                except Exception: continue
                mm = ch.get('message') or {}
                d = mm.get('content') or ''
                if d:
                    agg['message']['content'] += d
                    if not push(d): break
                t = (mm.get('thinking') or mm.get('reasoning_content') or '')
                if t: ths.append(t)
                for tc in (mm.get('tool_calls') or []): tcs.append(tc)
                for k in ('eval_count','eval_duration','total_duration','prompt_eval_count','done_reason','model'):
                    if k in ch: agg[k] = ch[k]
                if ch.get('done'): agg['done'] = True
    except Exception as e:
        err = str(e) or e.__class__.__name__
    finally:
        try:
            if c: c.close()
        except Exception: pass
    if tcs: agg['message']['tool_calls'] = tcs
    if ths: agg['message']['thinking'] = ''.join(ths)
    if not agg['message']['content'] and not tcs:
        # Streaming produced nothing. Try the same request without streaming
        # before giving up: a transport fault in one mode must not cost the
        # user their answer, and the reply is marked so nobody mistakes it for
        # a streamed one.
        try:
            fb = dict(payload)
            fb['stream'] = False
            res = ollama_chat(fb, timeout)
            m = res.get('message') or {}
            if m.get('content') or m.get('tool_calls'):
                if m.get('content'): push(m['content'])
                res['streaming'] = 'fallback-non-streaming'
                return res
            err = err or json.dumps(res)[:200]
        except Exception as e2:
            err = err or (str(e2) or e2.__class__.__name__)[:200]
        agg['message']['content'] = ('(engine error: '
                + (err or last or ('HTTP ' + str(status)))[:1200] + ')')
        agg['done'] = True
    return agg

LAST_HIT = {'t': time.time()}

def has_user_query(ms):
    """True when the chat template will accept this message list.

    The template scans BACKWARDS for a user message that is not wrapped in
    <tool_response> and calls raise_exception('No user query found in
    messages.') when it finds none. Tool results are rendered as user turns
    inside that tag, so they do not count. Checking here turns a malformed
    request into one clear line instead of an HTTP 500 that lands halfway
    through a turn with the UI already showing activity.
    """
    for m in reversed(ms):
        if m.get('role') != 'user':
            continue
        c = m.get('content')
        if isinstance(c, list):
            parts = []
            for x in c:
                if isinstance(x, dict):
                    parts.append(str(x.get('text') or ''))
            c = ' '.join(parts)
        c = str(c or '').strip()
        if not (c.startswith('<tool_response>') and c.endswith('</tool_response>')):
            return True
    return False

def history_window(msgs, max_msgs=24, max_chars=20000):
    """Pick the messages to send the way the chat template actually requires.

    The model's Jinja template scans BACKWARDS for the last user message that
    is not wrapped in <tool_response>, and raises 'No user query found
    in messages.' when it cannot find one. Tool results are rendered as user
    turns wrapped in that tag, so they never satisfy the check. A plain
    msgs[-24:] therefore drops the real question as soon as a conversation plus
    its tool traffic passes 24 messages, and the turn dies with HTTP 500
    halfway through -- reproduced against the live engine, which is exactly
    what a search-then-fetch-then-run turn hits.

    So the system prompt and the newest real user query are always kept, and
    older history is added back in complete assistant/tool pairs until the
    budget runs out.

    max_msgs governs ONLY the older history. The current turn is sent whole --
    a single turn can legitimately hold more messages than the cap, and
    dropping its tool results would blind the model to output it just asked
    for. What actually protects the context window is max_chars, so oversized
    tool results get trimmed instead. A long request always beats a 500.
    """
    def size(ms):
        return sum(len(str(m.get('content') or '')) for m in ms)
    if len(msgs) <= max_msgs and size(msgs) <= max_chars:
        return msgs
    head = []
    body = list(msgs)
    if body and body[0].get('role') == 'system':
        head = [body.pop(0)]
    last = -1
    for i, m in enumerate(body):
        if m.get('role') == 'user':
            last = i
    if last < 0:
        return (head + body)[-max_msgs:]
    tail = body[last:]
    older = body[:last]
    keep = []
    i = len(older)
    while i > 0:
        step = 2 if (older[i-1].get('role') == 'tool' and i >= 2
                     and older[i-2].get('role') == 'assistant') else 1
        cand = older[i-step:i]
        if len(head) + len(keep) + step + len(tail) > max_msgs:
            break
        if size(head + keep + cand + tail) > max_chars:
            break
        keep = cand + keep
        i -= step
    # If the current turn alone is too big, shrink its oldest tool results
    # rather than dropping the question or failing outright.
    j = 0
    while size(head + keep + tail) > max_chars and j < len(tail) - 1:
        m = tail[j]
        if m.get('role') == 'tool':
            c = str(m.get('content') or '')
            if len(c) > 400:
                m = dict(m); m['content'] = c[:400] + ' ...[truncated]'
                tail[j] = m
        j += 1
    return head + keep + tail

# Ollama's default context window is small. When a prompt exceeds it the
# messages are trimmed FROM THE FRONT, which drops the system prompt and the
# user's question -- and the chat template then raises 'No user query found in
# messages.' with HTTP 500 halfway through a turn. Measured on the live engine:
# the same 14-message tool turn fails at the default window and succeeds at
# 16384 (prompt_eval 5176 and 6262 tokens). So the window is declared here, and
# tool results are capped below, rather than left to chance.
NUM_CTX = 16384
TOOL_RESULT_MAX = 2500
# The model is a reasoning model (ollama reports the 'thinking' capability).
# It is ON: answers are better. It costs latency -- measured 2.3s vs 16.3s on a
# one-line puzzle -- so it is a single switch here rather than buried inline.
# The reasoning text itself is never shown to the user; the client drops it.
THINK = True
# Reasoning costs 25-65s of wall clock per model call on this kernel (measured),
# and a tool turn pays it on every iteration. Spending that on "what is the
# capital of France" is what made chat feel broken, so a turn only reasons when
# its prompt looks like it earns the cost. Set THINK_ALWAYS to force reasoning
# on every turn regardless.
THINK_ALWAYS = False
THINK_HINTS = ('why ', 'why?', 'compar', 'prove', 'calcul', 'comput', ' plan',
               'design', 'debug', 'optimi', 'analy', 'step by step', 'tradeoff',
               'trade-off', 'should i', 'which is better', 'review', 'refactor',
               'derive', 'estimate', 'strateg', 'architect', 'troubleshoot',
               'pros and cons', 'difference between')


def needs_reasoning(text):
    # Local import: this helper is defined above the tool layer's import
    # line, and depending on that ordering would break the moment anything
    # moved. Cached by the interpreter, so it costs nothing per call.
    import re as _re
    t = (text or '').lower()
    if len(t) >= 400:
        return True                      # a long brief deserves thought
    if t.count('?') >= 2:
        return True                      # multi-part question
    if any(h in t for h in THINK_HINTS):
        return True
    if _re.search(r'\d\s*[-+*/^%]\s*\d', t):
        return True                      # arithmetic in the prompt
    return False


def last_user_text(ms):
    for m in reversed(ms or []):
        if m.get('role') == 'user':
            c = m.get('content')
            if isinstance(c, str) and c.strip():
                return c
    return ''


def agent_stream(handler, user_payload):
    msgs = list(user_payload.get('messages') or [])
    # Older clients sent {"prompt": "..."} with no messages array at all. The
    # chat template scans backwards for a plain user message and raises 'No
    # user query found in messages.' without one, so that shape failed with
    # HTTP 500 on EVERY message -- including plain text with no tools involved.
    # Accept both shapes so an installed build can never hit it.
    if not msgs:
        pr = user_payload.get('prompt')
        if isinstance(pr, str) and pr.strip():
            msgs = [{'role': 'user', 'content': pr}]
    if not msgs or msgs[0].get('role') != 'system':
        msgs.insert(0, {'role':'system','content':SYSMSG})
    handler.send_response(200)
    handler.send_header('Content-Type','application/x-ndjson')
    handler.send_header('Transfer-Encoding','chunked')
    handler.send_header('Connection','close')
    handler.close_connection = True
    handler.end_headers()
    # FIX: mark the response as started THE MOMENT the status line goes out.
    # do_POST's error handler checks this; setting it only after agent_stream()
    # returns meant a mid-generation failure still wrote a second status line
    # into the open chunked body.
    handler._sent = True
    def emit(obj):
        try:
            line = (json.dumps(obj) + chr(10)).encode()
            handler.wfile.write(('%x\r\n' % len(line)).encode() + line + b'\r\n')
            handler.wfile.flush()
        except Exception: raise IOError('client gone')
    # Calls already made this turn. Measured on the live engine, the model can
    # re-issue the exact same three tool calls every iteration -- 20 calls over
    # 468s, and the turn still had not finished. Re-running identical work only
    # burns the user's time, so it is handed back from memory instead.
    seen_calls = set()
    # Decided once per turn from the user's own words, not per iteration, so the
    # turn cannot flip between reasoning and not halfway through.
    turn_think = THINK_ALWAYS or (THINK and needs_reasoning(last_user_text(msgs)))
    for it in range(10):
        window = history_window(msgs)
        if not has_user_query(window):
            emit({'message': {'content': '(the engine got this request with no user message in it, so there was nothing to answer - please send it again)'}, 'done': False})
            emit({'message': {'content': ''}, 'done': True, 'done_reason': 'stop'})
            try:
                handler.wfile.write(b'0\r\n\r\n'); handler.wfile.flush()
            except Exception: pass
            return
        payload = {'model': user_payload.get('model', MODEL), 'messages': window, 'stream': True, 'tools': TOOLS, 'think': turn_think, 'keep_alive': -1, 'options': {'num_ctx': NUM_CTX}}
        emit({'message':{'thinking':'⚙️ agent step ' + str(it+1) + '...'},'done':False})
        q = queue.Queue()
        st = {'gone': False, 'any': False}
        def push(d, st=st):
            if st['gone']: return False
            try:
                emit({'message':{'content': d}, 'done': False})
                st['any'] = True
                return True
            except Exception:
                st['gone'] = True
                return False
        tw = threading.Thread(target=lambda q=q, p=payload, s=push: q.put(ollama_stream(p, s)))
        tw.start()
        while tw.is_alive():
            emit({'message':{'thinking':'⏳'},'done':False})
            tw.join(timeout=10)
        resp = q.get()
        m = resp.get('message', {})
        _c0 = (m.get('content') or '')
        if _c0.startswith('(engine error'):
            # Publish the exact request shape that failed. A truncated template
            # error on its own is not enough to reproduce a request, and this
            # goes to the build host rather than into the user's chat.
            try:
                _r = ''.join({'system': 'S', 'user': 'U', 'assistant': 'A',
                              'tool': 'T'}.get(_x.get('role'), '?') for _x in window)
                notify('MODEL FAIL n=%d roles=%s has_user=%s err=%s' % (
                    len(window), _r[-48:], has_user_query(window), _c0[:400]))
                # The full payload, because reasoning about the shape from the
                # outside kept disagreeing with what the model server did.
                try:
                    notify('MODEL FAIL PAYLOAD ' + json.dumps(payload)[:2200])
                except Exception:
                    pass
            except Exception:
                pass
        tcs = m.get('tool_calls') or []
        if tcs and it < 9:
            # Classify first. A call already made this turn is answered from
            # memory and never re-run, exactly as before.
            plan = []
            repeats = 0
            for tc in tcs:
                fn = (tc.get('function') or {})
                name = fn.get('name','?'); args = fn.get('arguments') or {}
                if isinstance(args, str):
                    try: args = json.loads(args)
                    except Exception: args = {}
                _key = name + '|' + json.dumps(args, sort_keys=True, default=str)
                if _key in seen_calls:
                    repeats += 1
                    plan.append((name, args, True))
                else:
                    seen_calls.add(_key)
                    plan.append((name, args, False))

            def _run_one(nm, ar):
                try:
                    return EXEC.get(nm, lambda **k: 'unknown tool')(**ar)
                except Exception as e:
                    return 'tool error: ' + str(e)

            REPEAT_NOTE = ('This exact call was already made and its result is in the '
                           'conversation above. Do not call it again. Write your answer '
                           'now from what you already have.')
            results = [REPEAT_NOTE if rep else None for (_n, _a, rep) in plan]
            fresh = [(k, nm, ar) for k, (nm, ar, rep) in enumerate(plan) if not rep]

            # Independent calls now run concurrently. They used to run one after
            # another, so a step asking for three searches paid for all three in
            # series even though they share nothing. Four at a time leaves the
            # host enough room for the model itself.
            for k, nm, ar in fresh:
                emit({'message':{'thinking':'\U0001f6e0\ufe0f ' + nm + '(' + json.dumps(ar)[:180] + ')'},'done':False})
            if len(fresh) == 1:
                k, nm, ar = fresh[0]
                results[k] = _run_one(nm, ar)
                emit({'message':{'thinking':'\u21b3 ' + nm + ' returned ' + str(len(results[k])) + ' chars'},'done':False})
            elif len(fresh) > 1:
                import concurrent.futures as _cf
                with _cf.ThreadPoolExecutor(max_workers=min(4, len(fresh))) as _ex:
                    _futs = {_ex.submit(_run_one, nm, ar): (k, nm) for k, nm, ar in fresh}
                    for _f in _cf.as_completed(_futs):
                        k, nm = _futs[_f]
                        try: results[k] = _f.result()
                        except Exception as e: results[k] = 'tool error: ' + str(e)
                        emit({'message':{'thinking':'\u21b3 ' + nm + ' returned ' + str(len(results[k])) + ' chars'},'done':False})

            tool_msgs = []
            for k, (nm, ar, rep) in enumerate(plan):
                result = results[k] or ''
                # One huge search result can push the whole prompt past the
                # context window on its own, which is what trims the question
                # away. Keep the head of the result and say it was cut.
                if len(result) > TOOL_RESULT_MAX:
                    result = result[:TOOL_RESULT_MAX] + ' ...[truncated]'
                # Generated media is reported as a structured event so the
                # client can render and save it. Scraping the URL back out
                # of the model's prose is unreliable: the model may reword,
                # shorten or drop it entirely.
                if result.startswith('IMAGE READY: ') or result.startswith('AUDIO READY: '):
                    _kind = 'image' if result.startswith('IMAGE') else 'audio'
                    _u = result.split(':', 1)[1].strip().split(' ')[0]
                    if _u.startswith('http'):
                        emit({'media': {'kind': _kind, 'url': _u, 'source': nm},
                              'message': {'content': ''}, 'done': False})
                if not rep:
                    tool_msgs.append({'role':'tool','content': result, 'tool_name': nm})
            # The assistant message goes in ONCE, followed by one tool message
            # per call. It used to be appended inside the per-call loop, so a
            # step with three calls put three identical copies of the assistant
            # message into the prompt -- pure bloat, re-sent on every later
            # iteration and paid for in prompt evaluation each time.
            _am = {k2: v2 for k2, v2 in m.items() if k2 != 'thinking'}
            msgs.append(_am)
            msgs.extend(tool_msgs)
            if repeats and repeats == len(tcs):
                # Every call in this step was one it had already made: the model
                # is looping rather than answering. Stop and force the answer
                # instead of spending the remaining iterations on it.
                break
            continue
        th = (m.get('thinking') or '').strip()
        if th:
            emit({'message':{'thinking': th}, 'done': False})
        content = m.get('content') or ''
        # FIX (audit 4.9): the answer was already streamed token by token while
        # it was being generated. Re-emitting it here would double it, so this
        # only fires for the fallback text, which was never streamed.
        if not st['any']:
            if not content:
                content = '(I hit my tool-step limit before writing the final answer - please say retry)'
            emit({'message':{'content': content}, 'done': False})
        emit({'message':{'content':''}, 'done': True, 'done_reason':'stop', 'eval_count': resp.get('eval_count', 0), 'eval_duration': resp.get('eval_duration', 0), 'total_duration': resp.get('total_duration', 0), 'prompt_eval_count': resp.get('prompt_eval_count', 0)})
        try:
            handler.wfile.write(b'0\r\n\r\n'); handler.wfile.flush()
        except Exception: pass
        return
    final = {'model': user_payload.get('model', MODEL), 'messages': history_window(msgs), 'stream': True, 'keep_alive': -1, 'options': {'num_ctx': NUM_CTX}}
    p = subprocess.Popen(['curl','-s','-N','-m','1200','http://127.0.0.1:11434/api/chat','-d',json.dumps(final)], stdout=subprocess.PIPE)
    for raw in p.stdout:
        emit(json.loads(raw))
    try: p.kill()
    except Exception: pass
    try:
        handler.wfile.write(b'0\r\n\r\n'); handler.wfile.flush()
    except Exception: pass

